def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    prev_char = texto[0]
    count = 1
    for ch in texto[1:]:
        if ch == prev_char:
            count += 1
        else:
            result.append(f"{prev_char}{count}")
            prev_char = ch
            count = 1
    # Add the last group
    result.append(f"{prev_char}{count}")
    return "".join(result)
